import{_ as a,o,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"篇457｜龙珠·万族共和方案：打破人族/赛亚人本位","description":"","frontmatter":{"title":"篇457｜龙珠·万族共和方案：打破人族/赛亚人本位","no":457,"module":2,"tags":["诸天对标","龙珠","万族共和","赛亚人本位","种族平等","万族五大谱系"],"related":["0005-万族共进基本纲领","0050-万族谱系总览","0052-异族分类与共生"]},"headers":[],"relativePath":"zh/0457_模块2-龙珠-万族共和方案-打破人族赛亚人本位.md","filePath":"zh/0457_模块2-龙珠-万族共和方案-打破人族赛亚人本位.md"}'),e={name:"zh/0457_模块2-龙珠-万族共和方案-打破人族赛亚人本位.md"};function i(n,t,s,h,d,u){return o(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="篇457-龙珠·万族共和方案-打破人族-赛亚人本位" tabindex="-1">篇457｜龙珠·万族共和方案：打破人族/赛亚人本位 <a class="header-anchor" href="#篇457-龙珠·万族共和方案-打破人族-赛亚人本位" aria-label="Permalink to &quot;篇457｜龙珠·万族共和方案：打破人族/赛亚人本位&quot;">​</a></h1><blockquote><p>所属模块：模块二·诸天对标批判库｜系列：龙珠体系全套拆解（第26篇·替代方案6）｜对标地基：文档05、50、52</p></blockquote><h2 id="引言-当-最强种族-成为原罪" tabindex="-1">引言：当&quot;最强种族&quot;成为原罪 <a class="header-anchor" href="#引言-当-最强种族-成为原罪" aria-label="Permalink to &quot;引言：当&quot;最强种族&quot;成为原罪&quot;">​</a></h2><p>龙珠世界的种族秩序是：赛亚人（最强战斗种族）&gt; 地球人/那美克星人（普通智慧种族）&gt; 弗利萨军团下属种族（被征服者）&gt; 其他（背景板）。赛亚人种族本就是弗利萨军团的征服工具，悟空虽失忆，但他继承了这份种族原罪。本文以万族共和公理为核心，给出&quot;打破人族/赛亚人本位&quot;的共和方案。</p><p>本文评判底座为六大顶层公理（反掠夺主义公理、万族共和公理、集体升维公理、因果自律公理、法则优先公理、众生全员无限均等法则）与五大强制核心（反能级浪费、反掠夺、唐罗上限对比、万族全覆盖、超多元全开放），其中法则优先公理为核心。众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、该体系强者的「能级浪费」解析" tabindex="-1">一、该体系强者的「能级浪费」解析 <a class="header-anchor" href="#一、该体系强者的「能级浪费」解析" aria-label="Permalink to &quot;一、该体系强者的「能级浪费」解析&quot;">​</a></h2><p>赛亚人本位的能级浪费：</p><ul><li><strong>赛亚人天赋独占</strong>：濒死复活增益、超级赛亚人变身路线，全部只服务赛亚人</li><li><strong>万族天赋未开发</strong>：那美克星人的龙珠制造能力、亚德拉特星人的瞬间移动技术、佛利萨军团下属种族的各种天赋，全部被剧情性边缘化</li><li><strong>种族等级化</strong>：弗利萨军团下属种族被定义为&quot;被征服者&quot;，其文明价值归零</li></ul><h2 id="二、该文明为何必然历史倒退" tabindex="-1">二、该文明为何必然历史倒退 <a class="header-anchor" href="#二、该文明为何必然历史倒退" aria-label="Permalink to &quot;二、该文明为何必然历史倒退&quot;">​</a></h2><p>赛亚人本位如何喂养历史倒退：</p><ol><li><strong>万族无上升通道</strong>：赛亚人靠血统就能变身，万族再努力也追不上——文明向赛亚人一族倾斜</li><li><strong>被征服者无话语权</strong>：弗利萨军团下属种族在叙事里只是背景板，其苦难无人记录</li><li><strong>种族冲突循环</strong>：赛亚人曾是弗利萨的工具，悟空虽反水，但赛亚人种族的掠夺史从未被清算</li></ol><h2 id="三、主角掠夺思维深度拆解" tabindex="-1">三、主角掠夺思维深度拆解 <a class="header-anchor" href="#三、主角掠夺思维深度拆解" aria-label="Permalink to &quot;三、主角掠夺思维深度拆解&quot;">​</a></h2><p>悟空在赛亚人本位下的掠夺思维：</p><ul><li><strong>接受血统优越性</strong>：悟空从不质疑&quot;为什么赛亚人天生就能变超赛&quot;，他默认这是天经地义</li><li><strong>万族苦难被遗忘</strong>：贝吉塔行星被弗利萨毁灭，但悟空从不带领那美克星人、亚德拉特星人这些被赛亚人侵略过的种族讨回公道</li><li><strong>赛亚人=英雄叙事</strong>：整个龙珠世界的英雄叙事围绕赛亚人展开，万族在叙事里无位置</li></ul><h2 id="四、对比锚点共生的完善替代方案" tabindex="-1">四、对比锚点共生的完善替代方案 <a class="header-anchor" href="#四、对比锚点共生的完善替代方案" aria-label="Permalink to &quot;四、对比锚点共生的完善替代方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>龙珠赛亚人本位</th><th>锚点共和替代方案</th></tr></thead><tbody><tr><td>赛亚人天赋独占</td><td>万族五大谱系平等：碳基物质族/能量凝聚族/机械构造族/意识信息族/混合变异族</td></tr><tr><td>万族天赋未开发</td><td>三百套本源修炼体系六大类各50套，万族各族群有差异化修炼路径</td></tr><tr><td>弗利萨下属种族=背景板</td><td>0052-异族分类与共生：任何种族都纳入万族共和</td></tr><tr><td>赛亚人掠夺史未清算</td><td>反掠夺主义公理：赛亚人掠夺史入宪反省，不再作为英雄叙事</td></tr><tr><td>种族冲突循环</td><td>锚点议事会立法：种族平等入宪，任何种族歧视违宪</td></tr></tbody></table><h2 id="五、该体系纳入求索域模拟复盘方案" tabindex="-1">五、该体系纳入求索域模拟复盘方案 <a class="header-anchor" href="#五、该体系纳入求索域模拟复盘方案" aria-label="Permalink to &quot;五、该体系纳入求索域模拟复盘方案&quot;">​</a></h2><ol><li><strong>建模</strong>：求索沉淀域复刻龙珠世界，打破赛亚人本位</li><li><strong>变量</strong>：注入&quot;那美克星人龙珠制造能力公开&quot;&quot;亚德拉特星人瞬间移动技术教材化&quot;&quot;弗利萨下属种族纳入共和&quot;</li><li><strong>观测</strong>：统计万族修炼者出路率、种族冲突次数、文明长期建设率</li><li><strong>复盘</strong>：输出《打破赛亚人本位收益报告》，量化万族共和对龙珠世界的文明提升</li></ol><h2 id="六、设定自洽度-吃书烂尾风险评估" tabindex="-1">六、设定自洽度/吃书烂尾风险评估 <a class="header-anchor" href="#六、设定自洽度-吃书烂尾风险评估" aria-label="Permalink to &quot;六、设定自洽度/吃书烂尾风险评估&quot;">​</a></h2><ul><li><strong>赛亚人本位自洽度</strong>：低（超赛从千年传说贬值为血统标配）</li><li><strong>万族共和自洽度预期</strong>：高（万族五大谱系平等，修炼路径多元）</li><li><strong>吃书烂尾风险</strong>：从极高降至中（种族设定多元化后，不需要靠&quot;再加一个更强种族&quot;续命）</li><li><strong>主角唯一性依赖度</strong>：从高降至中低（赛亚人不再是唯一英雄种族）</li></ul><p><strong>新旧宇宙资源对标</strong>：旧宇宙资源与大道是有限的，必然掠夺内卷；锚点共生人人自带无限本源，掠夺失去意义。</p><h2 id="五大核心落点" tabindex="-1">五大核心落点 <a class="header-anchor" href="#五大核心落点" aria-label="Permalink to &quot;五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：那美克星人、亚德拉特星人的天赋全部开发</li><li><strong>反掠夺</strong>：赛亚人掠夺史入宪反省，种族歧视违宪</li><li><strong>唐罗上限对比</strong>：唐罗至少打破了人族内部的世家垄断，龙珠需要打破种族垄断</li><li><strong>万族全覆盖</strong>：万族五大谱系全部纳入共和，赛亚人不再本位</li><li><strong>超多元全开放</strong>：种族多元化让龙珠世界可真正扩容为多元宇宙联邦</li><li><strong>众生全员无限均等</strong>：基础无限之力人人自带，佛系保有保底、卷王可叠加更高，无限本源消弭掠夺动机，掠夺内卷从根上失去意义</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>打破赛亚人本位，不是要贬低悟空，而是要让万族不再活在&quot;赛亚人天生更强&quot;的阴影里。那美克星人会造龙珠、亚德拉特星人会瞬间移动、弗利萨下属种族有各种天赋——这些天赋不该被赛亚人的光芒掩盖。让万族各展所长、各修其道，龙珠世界才真正配得上&quot;宇宙&quot;二字。</p><p>说到底，本篇所述的龙珠·万族共和方案·打破人族赛亚人本位并非孤例——其因果与能级留痕全程纳入阿赖耶网络备案、可溯可校。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0456_模块2-龙珠-阿赖耶监管方案-杜绝战力膨胀的制度设计.html">篇456·阿赖耶监管</a> · <a href="./0458_模块2-龙珠-法则优先对照-衡元宙如何避免战力膨胀.html">篇458·法则优先对照</a> · <a href="/hengyuan-cosmos/zh/0005-万族共进基本纲领.html">0005-万族共进基本纲领</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',28)])])}const q=a(e,[["render",i]]);export{_ as __pageData,q as default};
